using Erp.Abstractions.Events;

namespace Erp.Modules.Accounting;

public enum AccountType { Asset, Liability, Equity, Revenue, Expense }
public enum NormalBalance { Debit, Credit }
public enum FiscalPeriodState { Open, Closed }
public enum JournalEntryState { Draft, Posted }
public enum CustomerInvoiceState { Draft, Posted, PartiallyPaid, Paid, Cancelled }
public enum SupplierBillState { Draft, Posted, PartiallyPaid, Paid, Cancelled }
public enum PaymentDirection { CustomerReceipt, SupplierPayment }
public enum PaymentState { Draft, Posted, Reversed }
public enum BankReconciliationState { Draft, Reconciled }
public sealed class Account { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public required string Code { get; set; } public required string Name { get; set; } public AccountType Type { get; set; } public NormalBalance NormalBalance { get; set; } public bool AllowDirectPosting { get; set; } = true; public bool IsActive { get; set; } = true; public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset UpdatedAtUtc { get; set; } public required string ConcurrencyStamp { get; set; } }
