public sealed class Journal { public Guid Id { get; set; } public Guid TenantId { get; set; } public Guid CompanyId { get; set; } public required string Code { get; set; } public required string Name { get; set; } public bool IsActive { get; set; } = true; public DateTimeOffset CreatedAtUtc { get; set; } public DateTimeOffset UpdatedAtUtc { get; set; } public required string ConcurrencyStamp { get; set; } }
